```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;

  return function (...args) {
    const now = Date.now();
    const remaining = wait - (now - last);

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = now;
      fn.apply(this, args);
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

function onScroll() {
  console.log(window.scrollY);
}

window.addEventListener('scroll', throttle(onScroll, 200), { passive: true });
```

First call fires at once, then at most once per 200 ms. Trailing timer makes sure the final scroll position gets handled.

To remove the listener later, keep a reference to the throttled function and pass that to `removeEventListener`.

