```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function encodeCursor(row) {
  return Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');
}

function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
    if (typeof ts !== 'string' || Number.isNaN(Date.parse(ts)) || !/^\d+$/.test(String(id))) {
      return null;
    }
    return [ts, String(id)];
  } catch {
    return null;
  }
}

router.get('/orders', async (req, res, next) => {
  try {
    let limit = DEFAULT_LIMIT;
    if (req.query.limit !== undefined) {
      limit = Number(req.query.limit);
      if (!Number.isInteger(limit) || limit < 1) {
        return res.status(400).json({ error: 'limit must be a positive integer' });
      }
      limit = Math.min(limit, MAX_LIMIT);
    }

    let where = '';
    const params = [];
    if (req.query.cursor !== undefined) {
      const decoded = decodeCursor(req.query.cursor);
      if (!decoded) {
        return res.status(400).json({ error: 'invalid cursor' });
      }
      params.push(...decoded);
      where = 'WHERE (created_at, id) < ($1::timestamptz, $2::bigint)';
    }

    // Fetch one extra row to know whether another page exists
    params.push(limit + 1);
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $${params.length}`,
      params
    );

    const hasMore = rows.length > limit;
    const page = hasMore ? rows.slice(0, limit) : rows;
    const nextCursor = hasMore ? encodeCursor(page[page.length - 1]) : null;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: nextCursor,
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

Index it needs:

```sql
CREATE INDEX orders_created_at_id_idx ON orders (created_at DESC, id DESC);
```

Client calls `GET /orders?limit=20`, then `GET /orders?limit=20&cursor=<next_cursor>` until `next_cursor` is `null`.

- **Cursor timestamp:** it comes from `created_at::text`, not the JS `Date`. `Date` drops microseconds, which would skip or repeat rows at page boundaries.
- **Assumed schema:** `id` is `bigint` and `created_at` is `timestamptz`. For a UUID `id`, change the `$2::bigint` cast and the `/^\d+$/` check.
- **Order:** newest first.

Hand-rolled parser, standard library only (`flag` is not used):

```go
package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, short, usage string
	def                string
	boolVal            *bool
	strVal             *string
}

func (f *flagDef) label() string {
	s := "    --" + f.name
	if f.short != "" {
		s = "-" + f.short + ", --" + f.name
	}
	if f.strVal != nil {
		s += " <value>"
	}
	return s
}

type positional struct {
	name, usage string
	val         *string
}

type Parser struct {
	name, desc  string
	flags       []*flagDef
	lookup      map[string]*flagDef
	positionals []*positional
	rest        []string
}

func NewParser(name, desc string) *Parser {
	return &Parser{name: name, desc: desc, lookup: map[string]*flagDef{}}
}

func (p *Parser) add(f *flagDef) {
	for _, key := range []string{f.name, f.short} {
		if key == "" {
			continue
		}
		if _, dup := p.lookup[key]; dup || key == "h" || key == "help" {
			panic("flag redefined: " + key)
		}
		p.lookup[key] = f
	}
	p.flags = append(p.flags, f)
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	v := new(bool)
	p.add(&flagDef{name: name, short: short, usage: usage, boolVal: v})
	return v
}

// String defines a flag that takes a value. short may be empty.
func (p *Parser) String(name, short, def, usage string) *string {
	v := new(string)
	*v = def
	p.add(&flagDef{name: name, short: short, usage: usage, def: def, strVal: v})
	return v
}

// Positional defines a required positional argument.
func (p *Parser) Positional(name, usage string) *string {
	v := new(string)
	p.positionals = append(p.positionals, &positional{name: name, usage: usage, val: v})
	return v
}

// Rest returns positional arguments beyond the defined ones.
func (p *Parser) Rest() []string { return p.rest }

func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			pos = append(pos, args[i+1:]...)
			break
		}
		if len(arg) < 2 || arg[0] != '-' {
			pos = append(pos, arg)
			continue
		}

		name, value, hasValue := strings.Cut(strings.TrimPrefix(arg[1:], "-"), "=")
		if name == "h" || name == "help" {
			return ErrHelp
		}
		f, ok := p.lookup[name]
		if !ok {
			return fmt.Errorf("unknown flag: %s", arg)
		}

		if f.boolVal != nil {
			if !hasValue {
				*f.boolVal = true
				continue
			}
			b, err := strconv.ParseBool(value)
			if err != nil {
				return fmt.Errorf("invalid boolean value %q for flag --%s", value, f.name)
			}
			*f.boolVal = b
			continue
		}

		if !hasValue {
			if i+1 >= len(args) {
				return fmt.Errorf("flag needs a value: %s", arg)
			}
			i++
			value = args[i]
		}
		*f.strVal = value
	}

	if len(pos) < len(p.positionals) {
		return fmt.Errorf("missing argument: <%s>", p.positionals[len(pos)].name)
	}
	for i, a := range p.positionals {
		*a.val = pos[i]
	}
	p.rest = pos[len(p.positionals):]
	return nil
}

func (p *Parser) PrintHelp(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [flags]", p.name)
	for _, a := range p.positionals {
		fmt.Fprintf(w, " <%s>", a.name)
	}
	fmt.Fprintln(w)
	if p.desc != "" {
		fmt.Fprintf(w, "\n%s\n", p.desc)
	}

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	if len(p.positionals) > 0 {
		fmt.Fprintln(tw, "\nArguments:")
		for _, a := range p.positionals {
			fmt.Fprintf(tw, "  %s\t%s\n", a.name, a.usage)
		}
	}
	fmt.Fprintln(tw, "\nFlags:")
	for _, f := range p.flags {
		usage := f.usage
		if f.strVal != nil && f.def != "" {
			usage += fmt.Sprintf(" (default %q)", f.def)
		}
		fmt.Fprintf(tw, "  %s\t%s\n", f.label(), usage)
	}
	fmt.Fprintf(tw, "  -h, --help\tshow this help\n")
	tw.Flush()
}

func main() {
	p := NewParser("greet", "Print a greeting into a file.")
	verbose := p.Bool("verbose", "v", "enable verbose output")
	name := p.String("name", "n", "world", "name to greet")
	file := p.Positional("file", "output file")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, ErrHelp) {
			p.PrintHelp(os.Stdout)
			return
		}
		fmt.Fprintln(os.Stderr, "error:", err)
		p.PrintHelp(os.Stderr)
		os.Exit(2)
	}

	fmt.Println(*verbose, *name, *file, p.Rest())
}
```

Generated help:

```
Usage: greet [flags] <file>

Print a greeting into a file.

Arguments:
  file  output file

Flags:
  -v, --verbose       enable verbose output
  -n, --name <value>  name to greet (default "world")
  -h, --help          show this help
```

Behavior:

- **Accepted forms:** `--name bob`, `--name=bob`, `-n bob`, `-n=bob`, `--verbose`, `--verbose=false`.
- **Positionals:** flags and positionals can interleave. `--` ends flag parsing; everything after is positional.
- **Extras:** defined positionals are required; any beyond them land in `Rest()`.
- **Not supported:** combined short flags (`-vn`) and attached short values (`-nbob`).
- **Dash-leading positionals:** a positional like `-5` is read as a flag. Pass it after `--`.

```ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly pending: Array<() => Promise<void>> = [];
  private idleWaiters: Array<() => void> = [];
  private running = 0;

  constructor(
    private readonly concurrency: number,
    private readonly maxRetries = 3,
  ) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError('concurrency must be a positive integer');
    }
  }

  /** Queues a job. Resolves with its result, or rejects with the last error once retries run out. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.runWithRetries(job));
        } catch (err) {
          reject(err);
        }
      });
      this.next();
    });
  }

  /** Resolves when nothing is running and nothing is waiting. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) {
      return Promise.resolve();
    }
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.maxRetries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const task = this.pending.shift()!;
      this.running++;
      // task never rejects: it settles the caller's promise instead
      void task().finally(() => {
        this.running--;
        this.next();
      });
    }

    if (this.running === 0 && this.pending.length === 0) {
      const waiters = this.idleWaiters;
      this.idleWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }
}
